<script setup lang="ts">import {ref} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/scenarios';import * as runs from '../api/runs';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import ScenarioStrip from '../components/ScenarioStrip.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{open:[string]}>();const name=ref('检修工作包·新风险情景'),pkg=ref('demo-package'),deadline=ref(32),samples=ref(1500),seed=ref(2410);const{busy,error,notice,act}=useAction();</script><template><Heading index="04 / IMMUTABLE SCENARIOS" title="截止期只问概率，不改写时差。" detail="每次保存新增工作包情景版本，冻结任务、FS边和三点范围。CPM/每次模拟LF均基于项目实际完工。"/><section v-if="canWrite" class="form-section"><form class="form-grid" @submit.prevent="act(async()=>{await create({name,package_id:pkg,deadline,samples,seed});await refresh()},'风险情景快照已冻结，可提交后台推演')"><label>情景名称<input aria-label="情景名称" v-model="name" required/></label><label>情景工作包<select aria-label="情景工作包" v-model="pkg"><option v-for="p in data.packages" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>截止期 / 小时<input aria-label="截止期小时" type="number" min="0" step="any" v-model.number="deadline"/></label><label>模拟样本数<input aria-label="模拟样本数" type="number" min="100" max="5000" step="1" v-model.number="samples"/></label><label>固定seed<input aria-label="固定seed" type="number" min="0" max="2147483647" step="1" v-model.number="seed"/></label><button class="primary" :disabled="busy">冻结风险情景</button></form><Notice :error="error" :notice="notice"/></section><Empty v-if="!data.scenarios.length">先导入工作包并建立无环FS依赖，再锁定截止期、样本数与seed。</Empty><article v-for="s in data.scenarios" :key="s.id" class="scenario-row"><div><p class="eyebrow">SNAPSHOT v{{s.version}} / {{s.snapshot.package.tasks.length}} TASKS / {{s.snapshot.dependencies.length}} EDGES</p><h2>{{s.name}}</h2><p>{{s.snapshot.package.source}}</p><ScenarioStrip :scenario="s"/></div><div><button v-if="canWrite" :disabled="busy" @click="act(async()=>{const r=await runs.create({scenario_id:s.id});await refresh();emit('open',r.id)},'风险任务已提交Redis')">运行CPM与风险 →</button><small>{{data.runs.filter(r=>r.scenario_id===s.id).length}}次独立运行</small></div></article><p class="footnote">Beta-PERT λ=4。a=m=b为常数，其余alpha=1+4(m-a)/(b-a)，beta=1+4(b-m)/(b-a)。固定seed与ID顺序复现，工期独立假设不包含天气共因。</p></template>